items.solution:
function saltedHash(password, salt) {
  const combined = password + salt;
  let hash = 0;
  for (let i = 0; i < combined.length; i++) {
    hash = (hash * 31 + combined.charCodeAt(i)) | 0;
  }
  return hash;
}
